def resolve(path, cwd, links):
    # Normalize the starting point
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]  # Skip empty first element from leading '/'
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Parse the target
            if target.startswith('/'):
                # Absolute link target
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative link target - relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                target_components = target.split('/')

            # Insert remaining components and target components
            components = target_components + components[i:]
            i = 0
        else:
            # Not a symlink, just move to this path
            current = candidate

    # Return the result, removing trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

